/*
 * tango_font.h -- the Tango menu font as compiled into the BL616 firmware.
 *
 * Tango. Our own code. The data (tango_font_data.c) and the constants (tango_model.h)
 * are GENERATED by menu-tango tools/osd-model/gen_font_c.py from the OSD model, so the firmware and the model
 * (and therefore the FPGA atlas) always agree. Font: Saira Condensed SemiBold, SIL OFL 1.1.
 */
#ifndef TANGO_FONT_H
#define TANGO_FONT_H

#include <stdint.h>
#include "tango_model.h"

typedef struct {
    uint16_t colbase;   /* first atlas column of the glyph */
    uint8_t  width;     /* columns stored (0 = no such glyph) */
    uint8_t  adv;       /* advance in pixels */
} tango_glyph_t;

/* ATLAS wire bytes: TANGO_FONT_COLS columns x TANGO_FONT_COL_BYTES, most significant byte first */
extern const uint8_t tango_font_atlas[TANGO_FONT_COLS * TANGO_FONT_COL_BYTES];
extern const tango_glyph_t tango_font_glyph[256];

/* icon codes drawn by the layout (zosd.Font._chevron) */
#define TANGO_ICON_CHEV_R  0x7f
#define TANGO_ICON_FOLDER  0x80
#define TANGO_ICON_UP      0x81
#define TANGO_ICON_CHECK   0x82
#define TANGO_ICON_CHEV_L  0x83
#define TANGO_ICON_SEG_ON  0x84
#define TANGO_ICON_SEG_OFF 0x85
#define TANGO_ICON_BRICK   0x86   /* the About wordmark's cell: solid, 4 px wide, full glyph height (zosd.Font) */

#endif
